begin;
create extension if not exists pgcrypto;
create type public.game_status as enum ('LOBBY','COUNTDOWN','QUESTION_OPEN','QUESTION_LOCKED','REVEAL','LEADERBOARD','FINAL_RESULTS','PAUSED','ENDED');
create type public.answer_option as enum ('A','B','C','D');

create table public.games(id uuid primary key default gen_random_uuid(),room_code text not null unique check(room_code~'^[0-9]{4,6}$'),status public.game_status not null default 'LOBBY',current_question_index int not null default 0 check(current_question_index between 0 and 9),question_started_at timestamptz,question_ends_at timestamptz,paused_from public.game_status,paused_remaining_ms int,created_at timestamptz not null default now());
create table public.questions(id uuid primary key default gen_random_uuid(),position int not null unique check(position between 1 and 10),question_text text not null,options jsonb not null check(options ?& array['A','B','C','D']),correct_option public.answer_option not null,difficulty text not null,max_points int not null check(max_points>0),explanation text not null);
create table public.teams(id uuid primary key default gen_random_uuid(),game_id uuid not null references public.games(id) on delete cascade,team_number int not null check(team_number between 1 and 7),auth_user_id uuid references auth.users(id) on delete set null,total_score int not null default 0 check(total_score>=0),streak int not null default 0,best_streak int not null default 0,boost_used boolean not null default false,joined_at timestamptz,unique(game_id,team_number),unique(game_id,auth_user_id));
create table public.answers(id uuid primary key default gen_random_uuid(),game_id uuid not null references public.games(id) on delete cascade,question_id uuid not null references public.questions(id),team_id uuid not null references public.teams(id) on delete cascade,selected_option public.answer_option not null,submitted_at timestamptz not null default now(),response_ms int not null check(response_ms>=0),is_correct boolean not null,accuracy_points int not null,speed_points int not null,boost_applied boolean not null default false,awarded_points int not null check(awarded_points>=0),unique(game_id,question_id,team_id));
create table public.game_events(id bigint generated always as identity primary key,game_id uuid not null references public.games(id) on delete cascade,room_code text not null,event_type text not null,team_number int,created_at timestamptz not null default now());
create index teams_game_idx on public.teams(game_id);create index answers_game_question_idx on public.answers(game_id,question_id);create index events_game_created_idx on public.game_events(game_id,created_at desc);

alter table public.games enable row level security;alter table public.questions enable row level security;alter table public.teams enable row level security;alter table public.answers enable row level security;alter table public.game_events enable row level security;
revoke all on public.games,public.questions,public.teams,public.answers,public.game_events from anon,authenticated;
grant select on public.game_events to authenticated;
create policy "authenticated can listen to safe events" on public.game_events for select to authenticated using(true);

create or replace function public.emit_event(p_game uuid,p_type text,p_team int default null) returns void language sql security definer set search_path='' as $$insert into public.game_events(game_id,room_code,event_type,team_number) select id,room_code,p_type,p_team from public.games where id=p_game$$;
revoke all on function public.emit_event(uuid,text,int) from public;

create or replace function public.create_game(p_room_code text) returns uuid language plpgsql security definer set search_path='' as $$declare g uuid;begin insert into public.games(room_code) values(p_room_code) returning id into g;insert into public.teams(game_id,team_number) select g,n from generate_series(1,7)n;perform public.emit_event(g,'CREATED');return g;end$$;
revoke all on function public.create_game(text) from public;grant execute on function public.create_game(text) to service_role;

create or replace function public.claim_team(p_room_code text,p_team_number int) returns jsonb language plpgsql security definer set search_path='' as $$declare g public.games;t public.teams;u uuid:=auth.uid();begin if u is null then raise exception 'unauthorized';end if;select * into g from public.games where room_code=p_room_code for update;if not found or g.status<>'LOBBY' then raise exception 'room unavailable';end if;if exists(select 1 from public.teams where game_id=g.id and auth_user_id=u) then return jsonb_build_object('accepted',true);end if;select * into t from public.teams where game_id=g.id and team_number=p_team_number for update;if t.auth_user_id is not null then raise exception 'team already claimed';end if;update public.teams set auth_user_id=u,joined_at=now() where id=t.id;perform public.emit_event(g.id,'TEAM_JOINED',p_team_number);return jsonb_build_object('accepted',true);end$$;
revoke all on function public.claim_team(text,int) from public;grant execute on function public.claim_team(text,int) to authenticated;

create or replace function public.submit_answer(p_room_code text,p_selected_option public.answer_option,p_use_boost boolean default false) returns jsonb language plpgsql security definer set search_path='' as $$declare g public.games;q public.questions;t public.teams;now_at timestamptz:=clock_timestamp();elapsed int;accuracy int;speed int;points int;correct boolean;begin select * into g from public.games where room_code=p_room_code for update;if not found or g.status<>'QUESTION_OPEN' then raise exception 'question not open';end if;if now_at>g.question_ends_at then raise exception 'answer expired';end if;select * into t from public.teams where game_id=g.id and auth_user_id=auth.uid() for update;if not found then raise exception 'not team representative';end if;select * into q from public.questions where position=g.current_question_index+1;if exists(select 1 from public.answers where game_id=g.id and question_id=q.id and team_id=t.id) then raise exception 'duplicate answer';end if;if p_use_boost and t.boost_used then raise exception 'boost already used';end if;elapsed:=greatest(0,least(15000,round(extract(epoch from(now_at-g.question_started_at))*1000)::int));correct:=p_selected_option=q.correct_option;accuracy:=case when correct then round(q.max_points*.60) else 0 end;speed:=case when correct then round(q.max_points*.40*greatest(0,(15000-elapsed)::numeric/15000)) else 0 end;points:=case when correct then round((accuracy+speed)*(case when p_use_boost then 1.5 else 1 end)) else 0 end;insert into public.answers(game_id,question_id,team_id,selected_option,submitted_at,response_ms,is_correct,accuracy_points,speed_points,boost_applied,awarded_points)values(g.id,q.id,t.id,p_selected_option,now_at,elapsed,correct,accuracy,speed,p_use_boost,points);update public.teams set total_score=total_score+points,streak=case when correct then streak+1 else 0 end,best_streak=greatest(best_streak,case when correct then streak+1 else 0 end),boost_used=boost_used or p_use_boost where id=t.id;perform public.emit_event(g.id,case when p_use_boost then 'BOOST_LOCKED' else 'ANSWER_LOCKED' end,t.team_number);if not exists(select 1 from public.teams x where x.game_id=g.id and x.auth_user_id is not null and not exists(select 1 from public.answers a where a.game_id=g.id and a.question_id=q.id and a.team_id=x.id)) then update public.games set status='QUESTION_LOCKED' where id=g.id;perform public.emit_event(g.id,'ALL_LOCKED');end if;return jsonb_build_object('accepted',true);exception when unique_violation then raise exception 'duplicate answer';end$$;
revoke all on function public.submit_answer(text,public.answer_option,boolean) from public;grant execute on function public.submit_answer(text,public.answer_option,boolean) to authenticated;

create or replace function public.public_snapshot(p_room_code text) returns jsonb language plpgsql security definer stable set search_path='' as $$declare g public.games;q jsonb:=null;reveal boolean;t jsonb;a jsonb;mine uuid;begin select * into g from public.games where room_code=p_room_code and status<>'ENDED';if not found then raise exception 'room not found';end if;reveal:=g.status in('REVEAL','LEADERBOARD','FINAL_RESULTS');select id into mine from public.teams where game_id=g.id and auth_user_id=auth.uid();if g.status not in('LOBBY','ENDED') then select jsonb_build_object('id',id,'position',position,'question_text',question_text,'options',options,'difficulty',difficulty,'max_points',max_points)||case when reveal then jsonb_build_object('correct_option',correct_option,'explanation',explanation) else '{}'::jsonb end into q from public.questions where position=g.current_question_index+1;end if;select coalesce(jsonb_agg(jsonb_build_object('id',id,'game_id',game_id,'team_number',team_number,'auth_user_id',case when auth_user_id is null then null else '00000000-0000-0000-0000-000000000000' end,'total_score',case when reveal or id=mine or g.status in('LEADERBOARD','FINAL_RESULTS') then total_score else 0 end,'streak',case when reveal then streak else 0 end,'best_streak',case when reveal then best_streak else 0 end,'boost_used',case when id=mine then boost_used else false end,'joined_at',joined_at) order by team_number),'[]') into t from public.teams where game_id=g.id;select coalesce(jsonb_agg(jsonb_build_object('team_id',team_id,'submitted_at',submitted_at,'response_ms',case when reveal then response_ms else 0 end,'boost_applied',boost_applied)||case when reveal then jsonb_build_object('is_correct',is_correct,'awarded_points',awarded_points) else '{}'::jsonb end),'[]') into a from public.answers where game_id=g.id and question_id=(select id from public.questions where position=g.current_question_index+1);return jsonb_build_object('game',to_jsonb(g),'teams',t,'question',q,'answers',a,'my_team_id',mine);end$$;
revoke all on function public.public_snapshot(text) from public;grant execute on function public.public_snapshot(text) to authenticated;

create or replace function public.host_snapshot(p_room_code text) returns jsonb language plpgsql security definer stable set search_path='' as $$declare g public.games;q jsonb:=null;t jsonb;a jsonb;begin select * into g from public.games where room_code=p_room_code;if not found then raise exception 'not found';end if;if g.status<>'LOBBY' then select to_jsonb(x) into q from public.questions x where position=g.current_question_index+1;end if;select coalesce(jsonb_agg(to_jsonb(x) order by team_number),'[]') into t from public.teams x where game_id=g.id;select coalesce(jsonb_agg(to_jsonb(x)),'[]') into a from public.answers x where game_id=g.id and (g.status='FINAL_RESULTS' or question_id=(select id from public.questions where position=g.current_question_index+1));return jsonb_build_object('game',to_jsonb(g),'teams',t,'question',q,'answers',a);end$$;
revoke all on function public.host_snapshot(text) from public;grant execute on function public.host_snapshot(text) to service_role;

create or replace function public.rebuild_team_scores(p_game uuid) returns void language plpgsql security definer set search_path='' as $$begin update public.teams t set total_score=coalesce((select sum(a.awarded_points) from public.answers a where a.team_id=t.id),0),boost_used=exists(select 1 from public.answers a where a.team_id=t.id and a.boost_applied),streak=0,best_streak=0 where t.game_id=p_game;end$$;revoke all on function public.rebuild_team_scores(uuid) from public;

create or replace function public.host_action(p_room_code text,p_action text,p_team_number int default null) returns jsonb language plpgsql security definer set search_path='' as $$declare g public.games;qid uuid;next_status public.game_status;begin select * into g from public.games where room_code=p_room_code for update;if not found then raise exception 'Phòng không tồn tại';end if;case p_action when 'START_GAME' then if g.status<>'LOBBY' then raise exception 'Trạng thái không hợp lệ';end if;update public.games set status='COUNTDOWN',current_question_index=0 where id=g.id;when 'START_QUESTION' then if g.status<>'COUNTDOWN' then raise exception 'Trạng thái không hợp lệ';end if;update public.games set status='QUESTION_OPEN',question_started_at=clock_timestamp(),question_ends_at=clock_timestamp()+interval '15 seconds' where id=g.id;when 'LOCK_QUESTION' then if g.status<>'QUESTION_OPEN' then raise exception 'Trạng thái không hợp lệ';end if;update public.games set status='QUESTION_LOCKED' where id=g.id;when 'REVEAL' then if g.status<>'QUESTION_LOCKED' then raise exception 'Trạng thái không hợp lệ';end if;update public.games set status='REVEAL' where id=g.id;when 'LEADERBOARD' then if g.status<>'REVEAL' then raise exception 'Trạng thái không hợp lệ';end if;update public.games set status='LEADERBOARD' where id=g.id;when 'NEXT' then if g.status<>'LEADERBOARD' then raise exception 'Trạng thái không hợp lệ';end if;if g.current_question_index=9 then update public.games set status='FINAL_RESULTS' where id=g.id;else update public.games set status='COUNTDOWN',current_question_index=current_question_index+1,question_started_at=null,question_ends_at=null where id=g.id;end if;when 'PAUSE' then if g.status in('LOBBY','PAUSED','ENDED','FINAL_RESULTS') then raise exception 'Không thể tạm dừng';end if;update public.games set paused_from=g.status,paused_remaining_ms=greatest(0,extract(epoch from(g.question_ends_at-clock_timestamp()))*1000),status='PAUSED' where id=g.id;when 'RESUME' then if g.status<>'PAUSED' then raise exception 'Game chưa tạm dừng';end if;update public.games set status=paused_from,question_started_at=case when paused_from='QUESTION_OPEN' then clock_timestamp()-(interval '15 seconds'-make_interval(secs=>paused_remaining_ms/1000.0)) else question_started_at end,question_ends_at=case when paused_from='QUESTION_OPEN' then clock_timestamp()+make_interval(secs=>paused_remaining_ms/1000.0) else question_ends_at end,paused_from=null where id=g.id;when 'UNLOCK_TEAM' then update public.teams set auth_user_id=null,joined_at=null where game_id=g.id and team_number=p_team_number;when 'RESET_QUESTION' then select id into qid from public.questions where position=g.current_question_index+1;delete from public.answers where game_id=g.id and question_id=qid;perform public.rebuild_team_scores(g.id);update public.games set status='COUNTDOWN',question_started_at=null,question_ends_at=null where id=g.id;when 'RESET_GAME' then delete from public.answers where game_id=g.id;update public.teams set total_score=0,streak=0,best_streak=0,boost_used=false where game_id=g.id;update public.games set status='LOBBY',current_question_index=0,question_started_at=null,question_ends_at=null,paused_from=null where id=g.id;when 'END_GAME' then update public.games set status='ENDED' where id=g.id;else raise exception 'Thao tác không hợp lệ';end case;perform public.emit_event(g.id,p_action,p_team_number);return jsonb_build_object('accepted',true);end$$;
revoke all on function public.host_action(text,text,int) from public;grant execute on function public.host_action(text,text,int) to service_role;

alter publication supabase_realtime add table public.game_events;
commit;
